        partial: T('Gövdenin bir kısmı görünüyor, uç düzlemin dışında: probu iğneye hizalayın.', 'Part of the shaft is visible but the tip is outside the plane: align the probe with the needle.', 'Se ve parte del cuerpo, pero la punta está fuera del plano: alinee la sonda con la aguja.'),
        none: T('İğne görüntü düzleminde değil.', 'The needle is not in the image plane.', 'La aguja no está en el plano de imagen.'),
        shaft: T('Dikkat: görünen nokta gövde, uç düzlemin ötesinde.', 'Caution: the visible dot is the shaft; the tip is beyond the plane.', 'Atención: el punto visible es el cuerpo; la punta está más allá del plano.'),
        dot: T('Uç düzlemde: ekrandaki nokta iğne ucu.', 'Tip in the plane: the dot on the screen is the needle tip.', 'Punta en el plano: el punto en la pantalla es la punta de la aguja.'),
        out: T('İğne henüz düzleme ulaşmadı.', 'The needle has not reached the plane yet.', 'La aguja aún no ha llegado al plano.'),
        skin: T('İğne cildin dışında.', 'The needle is outside the skin.', 'La aguja está fuera de la piel.')
