      'u-lens-c7': T(['Akustik yüzey · mikrokonveks', 'C7 HD3: 192 eleman, 20 mm kavis yarıçapı, 112° görüş alanı, 3–10 MHz, en fazla 18 cm (üretici verisi).'], ['Acoustic face · microconvex', 'C7 HD3: 192 elements, 20 mm radius, 112° field of view, 3–10 MHz, up to 18 cm (manufacturer data).'], ['Cara acústica · microconvexa', 'C7 HD3: 192 elementos, radio de 20 mm, campo de 112°, 3–10 MHz, hasta 18 cm (datos del fabricante).']),
      'u-lens-ec7': T(['Akustik yüzey · endokaviter', 'EC7 HD3: 192 eleman, 10 mm kavis yarıçapı, 164° görüş alanı, 3–10 MHz, en fazla 15 cm (üretici verisi).'], ['Acoustic face · endocavity', 'EC7 HD3: 192 elements, 10 mm radius, 164° field of view, 3–10 MHz, up to 15 cm (manufacturer data).'], ['Cara acústica · endocavitaria', 'EC7 HD3: 192 elementos, radio de 10 mm, campo de 164°, 3–10 MHz, hasta 15 cm (datos del fabricante).']),
      'u-lens-pa': T(['Akustik yüzey · fazlı dizi', 'PA HD3: 80 eleman, 90° sektör, 1–5 MHz, en fazla 40 cm (üretici verisi).'], ['Acoustic face · phased array', 'PA HD3: 80 elements, 90° sector, 1–5 MHz, up to 40 cm (manufacturer data).'], ['Cara acústica · matriz sectorial', 'PA HD3: 80 elementos, sector de 90°, 1–5 MHz, hasta 40 cm (datos del fabricante).']),
      'u-mark': T(['Yön işareti', 'Probun bir tarafını ekrandaki yön işaretiyle eşleştirir. İşlemden önce parmakla bastırma testiyle doğrulayın. Modeldeki yeri temsilidir.'], ['Orientation marker', 'Matches one side of the scanner to the marker on the screen. Confirm it with the finger-press test before the procedure. Its position on the model is representative.'], ['Marca de orientación', 'Hace corresponder un lado de la sonda con la marca de la pantalla. Confírmela con la prueba de presión antes del procedimiento. Su posición en el modelo es representativa.']),
      'u-btn': T(['Programlanabilir tuşlar', 'İki programlanabilir tuş vardır (üretici). Atanan işlevler uygulamadan seçilir; konumları modelde temsilidir.'], ['Programmable buttons', 'There are two programmable buttons (manufacturer). Their functions are assigned in the app; their position on the model is representative.'], ['Botones programables', 'Hay dos botones programables (fabricante). Sus funciones se asignan en la aplicación; su posición en el modelo es representativa.']),
      'u-led': T(['Durum ışığı', 'Probun durumunu bildirir; ışık anlamları için kullanım kılavuzuna bakın. Biçimi temsilidir.'], ['Status light', 'Shows the scanner\'s status; see the instructions for use for its meanings. Its shape is representative.'], ['Luz de estado', 'Indica el estado de la sonda; consulte las instrucciones de uso para su significado. Su forma es representativa.']),
      'u-body': T(['Gövde', 'Hafif magnezyum alaşım; IP67: 1 m suya 30 dakika daldırmaya dayanıklı (üretici). Ölçü ve ağırlık için bilgi kartına bakın.'], ['Housing', 'Lightweight magnesium alloy; IP67: withstands 1 m immersion for 30 minutes (manufacturer). See the info card for size and weight.'], ['Carcasa', 'Aleación ligera de magnesio; IP67: resiste la inmersión a 1 m durante 30 minutos (fabricante). Consulte la ficha para tamaño y peso.']),
      'u-batt': T(['Pil ve güç girişi (üst uç)', 'Pil gövdeye gömülüdür, çıkarılamaz: 60 dakikadan uzun tarama, 90 dakikadan uzun şarj, beklemede yaklaşık 7 gün (üretici) [2]. Güç probun üst (beyaz kapaklı) ucundan alınır: Power Fan HD3 bu uca takılır ve probu prizden ya da taşınabilir güç kaynağından besleyerek kesintisiz tarama sağlar; fan şarj tutmaz [22]. Modeldeki temas noktalarının biçimi temsilidir.'], ['Battery and power input (top end)', 'The battery is built in and cannot be removed: more than 60 minutes of scanning, more than 90 minutes to charge, about 7 days on standby (manufacturer) [2]. Power enters at the top (white-cap) end: the Power Fan HD3 snaps onto this end and powers the scanner from a wall outlet or power bank for uninterrupted scanning; the fan holds no charge [22]. The shape of the contacts in the model is representative.'], ['Batería y entrada de alimentación (extremo superior)', 'La batería está integrada y no se puede extraer: más de 60 minutos de exploración, más de 90 minutos de carga, unos 7 días en espera (fabricante) [2]. La alimentación entra por el extremo superior (tapa blanca): el Power Fan HD3 se acopla a este extremo y alimenta la sonda desde un enchufe o una batería externa para explorar sin interrupción; el ventilador no almacena carga [22]. La forma de los contactos en el modelo es representativa.']),
      'u-shaft': T(['Endokaviter şaft', 'EC7 HD3 toplam 310 mm; ince şaftın ucunda dizi bulunur (üretici).'], ['Endocavity shaft', 'The EC7 HD3 is 310 mm long overall; the array sits at the end of a slim shaft (manufacturer).'], ['Vástago endocavitario', 'La EC7 HD3 mide 310 mm en total; la matriz está en el extremo de un vástago fino (fabricante).']),
      'u-app': T(['Tablet · Clarius uygulaması', 'Görüntü Wi-Fi ile telefona ya da tablete gelir; uygulama iOS 16+ ve Android 13+ cihazlarda çalışır (üretici) [2]. Modeldeki yatay tablet genel bir 11 inç tablettir. Ekranına dokunarak modları deneyebilirsiniz; aynı ekranın büyük hali aşağıdaki Uygulama bölümündedir. Ekrandaki arayüz ve görüntü bu sayfanın benzetimidir.'], ['Tablet · Clarius app', 'The image reaches a phone or tablet over Wi-Fi; the app runs on iOS 16+ and Android 13+ devices (manufacturer) [2]. The landscape tablet in the model is a generic 11-inch tablet. Touch its screen to try the modes; a large version of the same screen is in the App section below. The interface and image on the screen are this page\'s simulation.'], ['Tableta · aplicación Clarius', 'La imagen llega a un teléfono o una tableta por Wi-Fi; la aplicación funciona en dispositivos iOS 16+ y Android 13+ (fabricante) [2]. La tableta horizontal del modelo es una tableta genérica de 11 pulgadas. Toque su pantalla para probar los modos; una versión grande de la misma pantalla está en la sección Aplicación, más abajo. La interfaz y la imagen de la pantalla son una simulación de esta página.']),
      'u-lens-pal': T(['Akustik yüzey · fazlı + lineer dizi', 'PAL HD3: fazlı dizi (90°) ve lineer dizi (29 mm) aynı başta birleşik; 1–15 MHz, en fazla 40 cm (üretici).'], ['Acoustic face · phased + linear array', 'PAL HD3: phased (90°) and linear (29 mm) arrays fused on one head; 1–15 MHz, up to 40 cm (manufacturer).'], ['Cara acústica · sectorial + lineal', 'PAL HD3: matrices sectorial (90°) y lineal (29 mm) en un solo cabezal; 1–15 MHz, hasta 40 cm (fabricante).']),
      'u-n-tip': T(['Bizo (iletken uç)', '20° veya 30° bizo seçenekleri vardır; yalnız bizonun ucu iletkendir (üretici). Modelde 30°.'], ['Bevel (conductive tip)', '20° or 30° bevel options; only the tip of the bevel is conductive (manufacturer). 30° on the model.'], ['Bisel (punta conductora)', 'Bisel de 20° o 30°; solo la punta del bisel es conductora (fabricante). 30° en el modelo.']),
      'u-n-echo': T(['Ekojenik uç bölge', 'Bizodan itibaren 2 cm kumlama (sandblasting) ile ekojenik yapılmıştır (üretici).'], ['Echogenic tip region', 'Made echogenic over 2 cm from the bevel by sandblasting (manufacturer).'], ['Zona ecogénica de la punta', 'Ecogénica en 2 cm desde el bisel mediante arenado (fabricante).']),
      'u-n-coat': T(['Yalıtım kaplaması', 'İğnenin tüm boyu yalıtkan kaplıdır; yalnız bizonun ucu iletken olduğundan elektriksel uyarı uçtan verilir (üretici).'], ['Insulating coating', 'The needle is insulated over its entire length; only the tip of the bevel is conductive, so the stimulus is delivered at the tip (manufacturer).'], ['Recubrimiento aislante', 'La aguja está aislada en toda su longitud; solo la punta del bisel es conductora, de modo que el estímulo sale por la punta (fabricante).']),
