      'u-n-cord': T(['Stimülasyon kablosu', '55 cm elektrik kablosu; sinir stimülatörüne bağlanır (üretici). Modelde kısaltılmıştır.'], ['Stimulation lead', '55 cm electrical cord that connects to the nerve stimulator (manufacturer). Shortened on the model.'], ['Cable de estimulación', 'Cable eléctrico de 55 cm que se conecta al neuroestimulador (fabricante). Acortado en el modelo.']),
      'u-p-lcd': T(['LCD ekran', 'Akımı mA veya uyarı başına elektrik yükünü nC olarak; ayrıca uyarı süresini (µs) ve frekansını (Hz) gösterir. Akım 0,5 mA’nın altındayken iki ondalık hane gösterilir (üretici). Değeri aşağıdaki panelden değiştirebilirsiniz.'], ['LCD screen', 'Displays current in mA or electric charge per pulse in nC, together with pulse width (µs) and frequency (Hz). Current below 0.5 mA is displayed with two decimal places (manufacturer). You can change the value using the panel below.'], ['Pantalla LCD', 'Muestra la corriente en mA o la carga eléctrica por pulso en nC, además de la duración del pulso (µs) y la frecuencia (Hz). Por debajo de 0,5 mA, la corriente se muestra con dos decimales (fabricante). Puede cambiar el valor desde el panel inferior.']),
      'u-p-knob': T(['Akım düğmesi', 'Uyarı akımını ayarlar: en fazla 4 mA (300 µs), 5 mA (100 µs) ya da 6 mA (50 µs); 0,5 mA altında 0,02 mA adımlarla (üretici).'], ['Current knob', 'Sets the stimulating current: up to 4 mA (300 µs), 5 mA (100 µs) or 6 mA (50 µs); 0.02 mA steps below 0.5 mA (manufacturer).'], ['Mando de corriente', 'Ajusta la corriente: hasta 4 mA (300 µs), 5 mA (100 µs) o 6 mA (50 µs); pasos de 0,02 mA por debajo de 0,5 mA (fabricante).']),
