      'u-p-safety': T(['SAFETY tuşu', 'Akımı hemen keser (üretici).'], ['SAFETY button', 'Cuts the current immediately (manufacturer).'], ['Botón SAFETY', 'Corta la corriente de inmediato (fabricante).']),
      'u-p-onoff': T(['ON/OFF tuşu', 'Cihazı açar ve kapatır.'], ['ON/OFF button', 'Switches the device on and off.'], ['Botón ON/OFF', 'Enciende y apaga el equipo.']),
      'u-p-side': T(['Yan kontrol paneli', 'Yan yüzde iki tuşlu panel; üst yüzde SIDE CTRL yazısıyla işaretlidir. İşlevleri için kullanım kılavuzuna bakın.'], ['Side control panel', 'A two-button panel on the side, marked SIDE CTRL on the top face. See the instructions for use for its functions.'], ['Panel de control lateral', 'Panel de dos botones en el lateral, señalado como SIDE CTRL en la cara superior. Consulte las instrucciones de uso.']),
      'u-p-sock': T(['Kablo çıkışları', 'İğne kablosu ve yüzey elektrodu kablosunun bağlandığı çıkışlar; modeldeki yerleri temsilidir.'], ['Lead sockets', 'Outputs for the needle lead and the skin electrode lead; their position on the model is representative.'], ['Conexiones', 'Salidas para el cable de la aguja y el del electrodo cutáneo; su posición en el modelo es representativa.']),
      'u-p-batt': T(['Pil', '9 V (500 mAh) pil; 24 saatten uzun sürekli çalışma. Taşıma çantasıyla gelir; steril koruyucu kılıf ayrıca bulunur (üretici).'], ['Battery', '9 V (500 mAh) battery; more than 24 hours of continuous use. Supplied with a carrying case; a sterile protective hood is sold separately (manufacturer).'], ['Batería', 'Pila de 9 V (500 mAh); más de 24 horas de uso continuo. Se suministra con estuche; la funda estéril se vende aparte (fabricante).']),
      'u-p-pad': T(['Yüzey (dönüş) elektrodu', 'Devreyi tamamlayan cilt elektrodu. Sabit akımlı stimülatörlerde yerleşim yeri motor yanıtı ya da gereken akımı değiştirmemiştir (Hadzic 2004).'], ['Skin (return) electrode', 'The skin electrode that completes the circuit. With constant-current stimulators its position did not change the motor response or the current required (Hadzic 2004).'], ['Electrodo cutáneo (retorno)', 'Electrodo que cierra el circuito. Con estimuladores de corriente constante, su posición no cambió la respuesta motora ni la corriente necesaria (Hadzic 2004).']),
      'u-n-marks': T(['Derinlik işaretleri', 'İlk 2 cm\'de milimetre, kalan boyda santimetre işaretleri; çift çizgi 5 cm\'yi gösterir (üretici).'], ['Depth markings', 'Millimeter marks over the first 2 cm and centimeter marks along the rest; a double mark indicates 5 cm (manufacturer).'], ['Marcas de profundidad', 'Marcas milimétricas en los primeros 2 cm y centimétricas en el resto; una doble marca indica 5 cm (fabricante).']),
      'u-n-hub': T(['Saydam ergonomik göbek', 'İyi kavrama için tasarlanmıştır; saydamlığı aspirasyon testinde kan geri gelişinin hızla görülmesini sağlar (üretici).'], ['Transparent ergonomic hub', 'Designed for a good grip; its transparency lets blood reflux be seen quickly during the aspiration test (manufacturer).'], ['Conector ergonómico transparente', 'Diseñado para un buen agarre; su transparencia permite ver rápidamente el reflujo de sangre en la prueba de aspiración (fabricante).']),
